"""Static checks for Terraform generated by the Terraform agent (no terraform binary, no cloud access).

terraform fmt / validate / plan run later, in the internal Git repository's CI on the merge request. These checks
catch what must never reach that MR. The model output is untrusted (prompt injection can arrive through uploads or
web search), so anything that would execute code or pull code during `terraform plan` in CI is refused outright:
`data "external"`, provisioners, `data "http"`, the external / null / http providers, and modules or providers
from sources that aren't allowlisted. On top of that come the organisation's baseline rules for strictly private
networks (templates/iac/standards.yaml).

A finding can be waived for ONE resource, with a reason that reviewers see in the merge request:
    # tfcheck:allow TF005 aws_security_group.alb public ALB for the customer website, approved in EXC-2026-014
Use the target "file" for a finding that isn't about a resource (e.g. TF009 on versions.tf). TF001 (parse),
TF003 (secrets) and TF015-TF017 (code execution / code sources) can't be waived.
"""

import re
from functools import lru_cache
from pathlib import Path

import hcl2
import yaml

STANDARDS = Path(__file__).resolve().parent / "templates" / "iac" / "standards.yaml"
ALLOW_RE = re.compile(r"#\s*tfcheck:allow\s+(TF\d{3})\s+([\w.\-\[\]\"]+)\s+(\S.{4,})")
SECRET_RES = [re.compile(p) for p in (r"AKIA[0-9A-Z]{16}", r"(?i)aws_secret_access_key\s*[=:]",
                                      r"-----BEGIN [A-Z ]*PRIVATE KEY-----")]
OPEN_CIDRS = {"0.0.0.0/0", "::/0"}
NOT_WAIVABLE = {"TF001", "TF003", "TF015", "TF016", "TF017"}
EXEC_DATA = {"external": "runs an arbitrary program during plan", "http": "makes arbitrary HTTP requests during plan"}
EXEC_PROVIDERS = {"external", "null", "http"}
PUBLIC_FLAGS = {"associate_public_ip_address", "map_public_ip_on_launch"}
MODULE_PUBLIC_INPUTS = {"enable_nat_gateway", "create_igw", "map_public_ip_on_launch", "single_nat_gateway",
                        "one_nat_gateway_per_az", "create_internet_gateway"}


@lru_cache(maxsize=1)
def standards() -> dict:
    return yaml.safe_load(STANDARDS.read_text(encoding="utf-8"))


def _clean(obj):
    """python-hcl2 keeps HCL quotes and adds __is_block__ markers; strip both."""
    if isinstance(obj, dict):
        return {_clean(k): _clean(v) for k, v in obj.items() if k != "__is_block__"}
    if isinstance(obj, list):
        return [_clean(v) for v in obj]
    if isinstance(obj, str) and len(obj) >= 2 and obj[0] == obj[-1] == '"':
        return obj[1:-1]
    return obj


def _blocks(parsed: dict, kind: str):
    """Yield (type or name, name or None, body) for top-level blocks of one kind."""
    for entry in parsed.get(kind, []):
        if not isinstance(entry, dict):
            continue
        if kind in ("terraform", "locals"):  # unlabelled blocks: the entry is the body
            yield kind, None, entry
            continue
        for typ, inner in entry.items():
            if kind in ("resource", "data"):
                for name, body in (inner or {}).items() if isinstance(inner, dict) else []:
                    yield typ, name, body if isinstance(body, dict) else {}
            else:
                yield typ, None, inner if isinstance(inner, dict) else {}


def _first(v):
    return v[0] if isinstance(v, list) and v else v


def _dicts(v) -> list[dict]:
    """A nested block may parse as a dict, a list of dicts, or an expression string; keep only literal blocks."""
    if isinstance(v, dict):
        return [v]
    return [x for x in v if isinstance(x, dict)] if isinstance(v, list) else []


def _strings(v) -> list[str]:
    return [x for x in v if isinstance(x, str)] if isinstance(v, list) else ([v] if isinstance(v, str) else [])


def _ingress_rules(body: dict) -> list[dict]:
    rules = _dicts(body.get("ingress"))
    for dyn in _dicts(body.get("dynamic")):  # dynamic "ingress" { content { ... } }
        for label, spec in dyn.items():
            if label == "ingress":
                for s in _dicts(spec):
                    rules += _dicts(s.get("content"))
    return rules


def _walk_blocks(body, path=()):
    """Every nested dict with its key path (to find provisioner blocks anywhere in a resource)."""
    if isinstance(body, dict):
        for k, v in body.items():
            yield path + (k,), v
            yield from _walk_blocks(v, path + (k,))
    elif isinstance(body, list):
        for v in body:
            yield from _walk_blocks(v, path)


def check(files: dict[str, str]) -> dict:
    std = standards()
    findings, parsed = [], {}
    module_ok = tuple(std.get("allowed_module_sources", []))
    provider_ok = tuple(std.get("allowed_provider_sources", ["hashicorp/"]))

    def add(rule, path, msg, severity="error", ref=None):
        findings.append({"rule": rule, "file": path, "severity": severity, "message": msg, "ref": ref})

    tf_files = {p: c for p, c in files.items() if p.endswith(".tf")}
    if not tf_files:
        add("TF000", "-", "No .tf files were generated.")
    for path, text in tf_files.items():
        try:
            parsed[path] = _clean(hcl2.loads(text))
        except Exception as e:  # noqa: BLE001 - any parser error is a finding
            add("TF001", path, f"HCL does not parse: {str(e).splitlines()[0][:300]}")
    for path, text in files.items():  # every file type: templates, JSON and YAML can carry secrets too
        for rx in SECRET_RES:
            if rx.search(text):
                add("TF003", path, "Looks like a credential or private key; use variables + Secrets Manager.")
        if re.search(r"\.tfvars(\.json)?$", path) or ".tfstate" in path:
            add("TF003", path, "Do not commit .tfvars / .auto.tfvars(.json) with values or state files; "
                               "commit *.tfvars.example instead.")

    # terraform block: versions pinned, provider sources, backend
    tblocks = [(p, b) for p, d in parsed.items() for _, _, b in _blocks(d, "terraform")]
    if parsed and not any(b.get("required_version") for _, b in tblocks):
        add("TF002", "versions.tf", "terraform { required_version } is not set.")
    providers_pinned = {}
    for p, b in tblocks:
        for rp in _dicts(b.get("required_providers")):
            for name, spec in rp.items():
                providers_pinned[name] = isinstance(spec, dict) and bool(spec.get("version"))
                if not providers_pinned[name]:
                    add("TF002", p, f"Provider '{name}' has no version constraint.")
                source = spec.get("source", f"hashicorp/{name}") if isinstance(spec, dict) else f"hashicorp/{name}"
                if name in EXEC_PROVIDERS or source.split("/")[-1] in EXEC_PROVIDERS:
                    add("TF015", p, f"Provider '{name}' can run code or fetch data during plan; not allowed.")
                elif not str(source).startswith(provider_ok):
                    add("TF017", p, f"Provider source '{source}' is not in allowed_provider_sources.")
    if parsed and not providers_pinned:
        add("TF002", "versions.tf", "terraform { required_providers } is missing.")
    if std.get("require_backend") and parsed and not any(b.get("backend") for _, b in tblocks):
        add("TF009", "versions.tf", "No backend block; state must use the team's remote backend.", "warning")

    # providers: credentials, default tags
    required_tags = std.get("required_tags", [])
    for p, d in parsed.items():
        for name, _, body in _blocks(d, "provider"):
            for key in ("access_key", "secret_key", "token"):
                if key in body:
                    add("TF003", p, f"provider '{name}' sets {key}; use the CI role instead.")
            if name in EXEC_PROVIDERS:
                add("TF015", p, f"provider '{name}' is not allowed.")
            if name == "aws" and required_tags:
                dt = _first(body.get("default_tags"))
                tags = dt.get("tags") if isinstance(dt, dict) else None
                missing = required_tags if not isinstance(tags, dict) else [t for t in required_tags if t not in tags]
                if missing:
                    add("TF007", p, f"provider aws default_tags is missing: {', '.join(missing)}.")

    # variables
    for p, d in parsed.items():
        for name, _, body in _blocks(d, "variable"):
            if not body.get("description") or not body.get("type"):
                add("TF004", p, f"variable '{name}' needs a type and a description.", "warning", f"var.{name}")
            if re.search(r"(?i)(password|secret|token|private_key)", str(name)) and body.get("sensitive") is not True:
                add("TF004", p, f"variable '{name}' looks secret; mark it sensitive = true.", ref=f"var.{name}")

    # data sources and modules: nothing that executes or pulls unreviewed code
    for p, d in parsed.items():
        for typ, name, _ in _blocks(d, "data"):
            if typ in EXEC_DATA:
                add("TF015", p, f'data "{typ}" "{name}" {EXEC_DATA[typ]}; not allowed.', ref=f"data.{typ}.{name}")
        for name, _, body in _blocks(d, "module"):
            src = str(body.get("source", ""))
            if not (src.startswith(("./", "../")) or (module_ok and src.startswith(module_ok))):
                add("TF016", p, f"module '{name}' source '{src}' is not local or in allowed_module_sources.",
                    ref=f"module.{name}")
            for key in MODULE_PUBLIC_INPUTS & set(body):
                if body[key] is True:
                    add("TF008", p, f"module '{name}': {key} = true creates internet paths.", ref=f"module.{name}")

    # resources
    types_present = {t for d in parsed.values() for t, _, _ in _blocks(d, "resource")}
    for p, d in parsed.items():
        for typ, name, body in _blocks(d, "resource"):
            ref = f"{typ}.{name}"
            if not re.fullmatch(r"[a-z0-9_]+", str(name)):
                add("TF013", p, f"{ref}: resource names must be snake_case.", "warning", ref)
            if any(path[-1] == "provisioner" for path, _ in _walk_blocks(body)):
                add("TF015", p, f"{ref}: provisioners run commands in CI; not allowed.", ref=ref)
            if typ in ("null_resource", "terraform_data") and body:
                add("TF015", p, f"{ref}: {typ} is only used for provisioners / triggers; not allowed.", ref=ref)
            open_rule = False
            if typ == "aws_security_group":
                for rule in _ingress_rules(body):
                    cidrs = _strings(rule.get("cidr_blocks")) + _strings(rule.get("ipv6_cidr_blocks"))
                    open_rule |= bool(OPEN_CIDRS & set(cidrs))
                    if any("${" in c for c in cidrs):
                        add("TF005", p, f"{ref}: ingress CIDRs come from an expression; reviewers must confirm "
                                        "they can't be 0.0.0.0/0.", "warning", ref)
                if isinstance(body.get("ingress"), str):
                    add("TF005", p, f"{ref}: ingress rules come from an expression; review them.", "warning", ref)
            if typ == "aws_security_group_rule" and body.get("type") == "ingress":
                open_rule |= bool(OPEN_CIDRS & set(_strings(body.get("cidr_blocks")) + _strings(body.get("ipv6_cidr_blocks"))))
            if typ == "aws_vpc_security_group_ingress_rule":
                open_rule |= body.get("cidr_ipv4") in OPEN_CIDRS or body.get("cidr_ipv6") in OPEN_CIDRS
            if open_rule:
                add("TF005", p, f"{ref}: ingress open to the internet.", ref=ref)
            if typ in std.get("forbidden_resources", {}):
                add("TF008", p, f"{ref}: {std['forbidden_resources'][typ]}", ref=ref)
            for flag in PUBLIC_FLAGS:
                if body.get(flag) is True or any(isinstance(b, dict) and b.get(flag) is True
                                                 for b in _dicts(body.get("network_interfaces"))):
                    add("TF008", p, f"{ref}: {flag} = true gives public IPs.", ref=ref)
            if typ in ("aws_db_instance", "aws_rds_cluster"):
                if body.get("storage_encrypted") is not True:
                    add("TF010", p, f"{ref}: storage_encrypted must be true.", ref=ref)
                if body.get("publicly_accessible") is True:
                    add("TF010", p, f"{ref}: publicly_accessible must not be true.", ref=ref)
            if typ == "aws_kms_key" and body.get("enable_key_rotation") is not True:
                add("TF011", p, f"{ref}: enable_key_rotation must be true.", ref=ref)
            if typ in ("aws_instance", "aws_launch_template"):
                mo = _first(body.get("metadata_options"))
                if not isinstance(mo, dict) or mo.get("http_tokens") != "required":
                    add("TF012", p, f"{ref}: IMDSv2 required (metadata_options {{ http_tokens = \"required\" }}).",
                        ref=ref)
    if "aws_s3_bucket" in types_present:
        for needed in ("aws_s3_bucket_public_access_block", "aws_s3_bucket_server_side_encryption_configuration"):
            if needed not in types_present:
                add("TF006", "-", f"S3 buckets need {needed}.")

    for f in std.get("required_files", []):
        if not any(p == f or p.endswith("/" + f) for p in files):
            add("TF014", f, f"Missing {f}.", "warning")

    # waivers: one rule, one resource (or "file"), with a reason
    waivers = {}
    for path, text in files.items():
        for rule, target, reason in ALLOW_RE.findall(text):
            waivers[(path, rule, target)] = reason.strip()
    for f in findings:
        reason = waivers.get((f["file"], f["rule"], f["ref"] or "file"))
        if reason and f["rule"] not in NOT_WAIVABLE:
            f["severity"], f["waived"] = "waived", reason
    errors = [f for f in findings if f["severity"] == "error"]
    return {"ok": not errors, "errors": len(errors), "warnings": sum(f["severity"] == "warning" for f in findings),
            "waived": sum(f["severity"] == "waived" for f in findings), "findings": findings, "files": sorted(files)}


def problems_for_repair(report: dict) -> list[str]:
    return [f"[{f['rule']}] {f['file']}: {f['message']}" for f in report["findings"] if f["severity"] == "error"]
